  @override
  String get batchDlgHelpBody =>
      '1. Choisissez un préréglage ou activez des règles, puis copiez les règles et réorganisez-les au besoin.\n\n2. L’aperçu affiche les noms qui seront utilisés. La recherche et les filtres modifient uniquement l’affichage. Décocher un élément l’exclut et recalcule la numérotation. Modifiez un nom individuellement ou rétablissez le résultat de la règle.\n\n3. Résolvez tous les problèmes avant de lancer l’opération. Les suffixes automatiques évitent les doublons sans écraser de fichiers. Renommez les dossiers qui échangent leurs noms en plusieurs opérations distinctes.\n\n4. Vous pouvez arrêter le traitement des éléments suivants pendant l’exécution ; l’élément en cours est d’abord terminé. La page des résultats affiche les modifications effectuées et permet de les annuler. L’annulation est bloquée si la liste a changé depuis l’exécution.\n\nSeuls les noms et les chemins des dossiers sont modifiés ; le contenu des fichiers et leurs extensions restent inchangés. Renommer un dossier parent n’empêche pas le renommage des éléments enfants cochés, et le renommage du parent déplace aussi ses enfants.';

