  @override
  String get platformTutorialAndroidStep4Description =>
      'Android 13 et les versions ultérieures nécessitent l’autorisation d’afficher des notifications. Sans celle-ci, la notification permanente du service en arrière-plan est masquée, même si le service continue de fonctionner. L’application demande cette autorisation la première fois que vous appuyez sur « Démarrer le service » ; vous pouvez aussi l’activer dans Paramètres → Applications → Stroom → Notifications.';

  @override
  String get platformTutorialAndroidStep5Title =>
      'Ignorer l’optimisation de la batterie';

  @override
  String get platformTutorialAndroidStep5Description =>
      'Lorsque vous activez les « Notifications de fin de tâche » dans Stroom, l’application demande l’autorisation correspondante. Vous pouvez aussi vérifier que Stroom est réglé sur « Ne pas optimiser » dans Paramètres → Applications → Accès spécial des applications → Optimisation de la batterie.';

  @override
  String get platformTutorialAndroidStep6Title =>
      'Démarrage automatique et gestion de l’arrière-plan sur les appareils Android';

  @override
  String get platformTutorialAndroidStep6Description =>
      'Les fabricants d’appareils ajoutent souvent leurs propres contrôles de l’exécution en arrière-plan :\n• Xiaomi/Redmi (MIUI/HyperOS) : Paramètres → Applications → Autorisations → Démarrage automatique ; autorisez Stroom. Puis accédez à Batterie → Économiseur de batterie des applications → Stroom → Aucune restriction.\n• Huawei/Honor (EMUI/HarmonyOS) : Paramètres → Applications → Lancement des applications → Stroom → Gérer manuellement ; autorisez le lancement automatique, le lancement secondaire et l’activité en arrière-plan.\n• OPPO/OnePlus/realme (ColorOS) : Paramètres → Batterie → Gestion de la batterie des applications → Stroom ; autorisez toute l’activité en arrière-plan.\n• vivo/iQOO (OriginOS) : iManager → Gestion des applications → Démarrage automatique ; autorisez Stroom.';

  @override
  String get platformTutorialAndroidStep7Title =>
      'Désactiver le nettoyage au verrouillage et les modes d’économie d’énergie';

  @override
  String get platformTutorialAndroidStep7Description =>
      'Ouvrez Paramètres → Batterie et désactivez « Économie d’énergie » ou « Ultra économie d’énergie ». Réglez également « Effacer la mémoire après le verrouillage » sur « Ne pas effacer ». Les modes d’économie d’énergie limitent l’activité en arrière-plan et peuvent empêcher les tâches d’aboutir.';

  @override
  String get platformTutorialIosStep1Title =>
      'Activer l’actualisation en arrière-plan';

  @override
  String get platformTutorialIosStep1Description =>
      'Ouvrez Réglages → Général → Actualisation en arrière-plan, repérez Stroom et activez l’option. Pour une expérience optimale, choisissez « Wi-Fi et données cellulaires ».';

  @override
  String get platformTutorialIosStep2Title => 'Autoriser les notifications';

  @override
  String get platformTutorialIosStep2Description =>
      'Ouvrez Réglages → Notifications → Stroom et activez « Autoriser les notifications ». Activez les bannières et le Centre de notifications pour suivre rapidement l’avancement des tâches.';

  @override
  String get platformTutorialIosStep3Title =>
      'Désactiver le mode économie d’énergie';

  @override
  String get platformTutorialIosStep3Description =>
      'Ouvrez Réglages → Batterie et désactivez le « Mode économie d’énergie ». Lorsque ce mode est activé, le système limite l’activité en arrière-plan.';

  @override
  String get platformTutorialIosStep4Title =>
      'Comprendre les limites de l’arrière-plan sous iOS';

  @override
  String get platformTutorialIosStep4Description =>
      'Les versions antérieures à iOS 26 ne permettent pas aux apps de rester en arrière-plan comme sur Android. Le système ne leur accorde que de brèves périodes d’exécution à certains moments, par exemple lors de l’actualisation en arrière-plan, de mises à jour de localisation ou de la lecture audio, et peut suspendre les tâches de longue durée. Nous vous recommandons de :\n• Garder Stroom au premier plan pour les tâches de longue durée.\n• Revenir régulièrement dans l’application pour renouveler son temps d’exécution en arrière-plan.\n• Activer les « Notifications de fin de tâche » pour les tâches importantes.';

  @override
  String get platformTutorialIosStep5Title =>
      'Conseils lorsque des tâches sont en cours';

  @override
  String get platformTutorialIosStep5Description =>
      'iOS 26 et les versions ultérieures prennent en charge les tâches persistantes en arrière-plan. Les tâches continuent généralement si vous changez d’application ou verrouillez l’écran, mais le système peut les arrêter lorsque les ressources sont limitées ; leur progression s’affiche sur l’écran verrouillé.\n\nLes versions antérieures d’iOS ne prennent pas en charge les tâches persistantes en arrière-plan. Revenez dans l’application toutes les quelques minutes (5 à 10 minutes est une indication ; le système décide) pour renouveler le temps d’exécution en arrière-plan et éviter sa suspension.\n\nQuelle que soit la version, ne balayez pas Stroom vers le haut dans le sélecteur d’apps : cela arrête immédiatement toutes les tâches en cours.';

  @override
  String get platformTutorialIosStep6Title =>
      'Garder l’application au premier plan';

  @override
  String get platformTutorialIosStep6Description =>
      'Avant iOS 26, les applications disposent de peu de temps en arrière-plan. Pour les tâches de longue durée, gardez Stroom au premier plan ou revenez-y régulièrement pour prolonger ce temps.';

  @override
  String get platformTutorialWindowsStep1Title =>
      'Réduire dans la zone de notification à la fermeture de la fenêtre';

  @override
  String get platformTutorialWindowsStep1Description =>
      'Par défaut, le bouton de fermeture réduit Stroom dans la zone de notification (près de l’horloge), ce qui lui permet de continuer à fonctionner. Rouvrez l’application depuis son icône ou le menu « Afficher la fenêtre principale ». Ne quittez pas l’application pendant l’exécution de tâches. Pour quitter, utilisez « Quitter complètement l’application » sur la page « Optimisation de l’exécution en arrière-plan » ou choisissez « Quitter Stroom » dans le menu de la zone de notification.';

  @override
  String get platformTutorialWindowsStep2Title =>
      'Désactiver l’économiseur de batterie';

  @override
  String get platformTutorialWindowsStep2Description =>
      'Ouvrez Paramètres → Système → Alimentation et mise en veille, puis désactivez l’économiseur de batterie. Vous pouvez aussi le configurer pour qu’il ne s’active qu’en dessous d’un niveau de batterie défini.';

  @override
  String get platformTutorialWindowsStep3Title =>
      'Autoriser les applications en arrière-plan';

  @override
  String get platformTutorialWindowsStep3Description =>
      'Ouvrez Paramètres → Confidentialité et sécurité → Applications en arrière-plan, repérez Stroom et vérifiez que l’option est activée. Sous Windows 11, accédez à Paramètres → Applications → Applications installées → Stroom → Options avancées → Autorisations des applications en arrière-plan et choisissez « Toujours ».';

  @override
  String get platformTutorialWindowsStep4Title =>
      'Désactiver la mise en veille (facultatif)';

  @override
  String get platformTutorialWindowsStep4Description =>
      'Pour que Stroom continue de fonctionner longtemps, ouvrez Paramètres → Système → Alimentation et réglez « Veille » sur « Jamais » (uniquement lorsque l’appareil est branché).';

  @override
  String get platformTutorialWindowsStep5Title => 'Ajouter Stroom au démarrage';

  @override
  String get platformTutorialWindowsStep5Description =>
      'Ouvrez le Gestionnaire des tâches (Ctrl+Maj+Échap) → Applications de démarrage, repérez Stroom et faites un clic droit sur « Activer ». Vous pouvez aussi ouvrir Paramètres → Applications → Démarrage et activer Stroom.';

  @override
  String get platformTutorialMacosStep1Title =>
      'Réduire la fenêtre à la fermeture';

  @override
  String get platformTutorialMacosStep1Description =>
      'Par défaut, la fermeture de la fenêtre laisse Stroom actif dans la barre des menus (en haut à droite de l’écran). Cliquez sur son icône dans la barre des menus ou choisissez « Afficher la fenêtre principale » pour la rouvrir. Ne quittez pas l’application pendant l’exécution de tâches. Pour quitter, utilisez « Quitter complètement l’application » sur la page « Optimisation en arrière-plan » ou choisissez « Quitter Stroom » dans le menu de la barre des menus.';

  @override
  String get platformTutorialMacosStep2Title => 'Autoriser les notifications';

  @override
  String get platformTutorialMacosStep2Description =>
      'Ouvrez Réglages Système → Notifications → Stroom, puis activez « Autoriser les notifications ». Nous vous recommandons d’activer les bannières et le Centre de notifications.';

  @override
  String get platformTutorialMacosStep3Title =>
      'Désactiver le mode économie d’énergie (MacBook)';

  @override
  String get platformTutorialMacosStep3Description =>
      'Ouvrez Réglages Système → Batterie → Adaptateur secteur, puis désactivez « Mode économie d’énergie ». Ce mode limite l’activité en arrière-plan.';

  @override
  String get platformTutorialMacosStep4Title => 'Garder l’application active';

  @override
  String get platformTutorialMacosStep4Description =>
      'macOS impose peu de restrictions aux applications en arrière-plan. Pour les tâches de longue durée, laissez la fenêtre de Stroom ouverte. Évitez de forcer la fermeture de l’application ; fermer la fenêtre suffit.';

  @override
  String get platformTutorialMacosStep5Title =>
      'Lancer à l’ouverture de session (facultatif)';

  @override
  String get platformTutorialMacosStep5Description =>
      'Ouvrez Réglages Système → Général → Ouverture, puis ajoutez Stroom pour qu’il démarre automatiquement à l’allumage de votre ordinateur.';

  @override
  String get platformTutorialLinuxStep1Title =>
      'Réduire la fenêtre à la fermeture';

  @override
  String get platformTutorialLinuxStep1Description =>
      'Par défaut, la fermeture de la fenêtre masque Stroom dans la zone de notification (nécessite un environnement de bureau compatible avec StatusNotifierItem et libayatana-appindicator3-dev au moment de la compilation). Rouvrez l’application depuis le menu de la zone de notification en choisissant « Afficher la fenêtre principale ». Ne quittez pas l’application pendant l’exécution de tâches. Pour quitter, utilisez « Quitter complètement l’application » sur la page « Optimisation en arrière-plan » ou choisissez « Quitter Stroom » dans le menu de la zone de notification.';

  @override
  String get platformTutorialLinuxStep2Title =>
      'Paramètres de l’environnement de bureau';

  @override
  String get platformTutorialLinuxStep2Description =>
      'Selon votre environnement de bureau (GNOME, KDE, XFCE, etc.), ouvrez les Paramètres système → Applications, recherchez Stroom et vérifiez que son activité en arrière-plan n’est pas limitée.';

  @override
  String get platformTutorialLinuxStep3Title =>
      'Utiliser un service systemd (facultatif)';

  @override
  String get platformTutorialLinuxStep3Description =>
      'Pour les tâches en arrière-plan de longue durée, créez un service systemd utilisateur. Créez un fichier stroom.service dans ~/.config/systemd/user/ et définissez ExecStart sur l’exécutable Stroom.';

  @override
  String get platformTutorialLinuxStep4Title => 'Désactiver la mise en veille';

  @override
  String get platformTutorialLinuxStep4Description =>
      'Sur un serveur ou un ordinateur de bureau devant fonctionner longtemps, définissez HandleLidSwitch=ignore dans /etc/systemd/logind.conf pour empêcher la mise en veille à la fermeture du capot.';

  @override
  String get platformTutorialLinuxStep5Title =>
      'Activer le démarrage automatique';

  @override
  String get platformTutorialLinuxStep5Description =>
      'Sous GNOME, utilisez Ajustements → Applications au démarrage → Ajouter Stroom. Vous pouvez aussi créer un fichier stroom.desktop dans ~/.config/autostart/.';

  @override
  String get platformTutorialWebStep1Title => 'Garder l’onglet ouvert';

  @override
  String get platformTutorialWebStep1Description =>
      'Les navigateurs web ne prennent pas en charge les services en arrière-plan. Gardez l’onglet Stroom ouvert pendant l’exécution des tâches ; fermer l’onglet ou actualiser la page les interrompt immédiatement.';

  @override
  String get platformTutorialWebStep2Title =>
      'Empêcher la suspension de l’onglet par le navigateur';

  @override
  String get platformTutorialWebStep2Description =>
      'Les navigateurs peuvent figer les onglets inactifs en arrière-plan pour économiser les ressources. Gardez l’onglet Stroom au premier plan pendant l’exécution des tâches ou interagissez régulièrement avec la page pour la maintenir active.';

