  @override
  String get backgroundOptimizationColdStartTitle =>
      'Rétablir le service au lancement de l’application';

  @override
  String get backgroundOptimizationColdStartDetail =>
      'Lorsque cette option est activée, l’application vérifie et rétablit un service en arrière-plan déjà actif à chaque ouverture.\n\nSi le système ou l’utilisateur arrête le processus de l’application, le service en arrière-plan redémarre à la prochaine ouverture de l’application.\n\nRecommandé à tout le monde.\nImpact sur la batterie : aucun ; l’application vérifie uniquement au démarrage.';

  @override
  String get backgroundOptimizationSaveColdStartFailed =>
