  @override
  String get backgroundOptimizationBatteryReminderTitle =>
      'Rappel d’optimisation de la batterie';

  @override
  String get backgroundOptimizationBatteryReminderDetail =>
      'Lorsque cette option est activée, cette page affiche l’état de l’optimisation de la batterie. Si l’application ne figure pas dans la liste d’exemption de la batterie, vous pouvez ouvrir les paramètres système pour l’y ajouter.\n\nL’optimisation de la batterie Android (Doze) limite les applications en arrière-plan. Ajouter cette application à la liste d’exemption empêche le système de l’arrêter pour économiser de l’énergie.\n\nDésactiver cette option masque uniquement la carte de rappel ; cela ne modifie pas l’exemption de batterie de l’application.';

  @override
  String get backgroundOptimizationStrategyIntro =>
      'Ces stratégies peuvent être activées indépendamment. Elles sont toutes activées par défaut pour garantir l’activité en arrière-plan la plus fiable. En désactiver une ne concerne que cette stratégie, et non le service en arrière-plan lui-même.';

