  @override
  String asrFailureDiagnosticFormat(
    Object category,
    Object stage,
    Object chunk,
    Object message,
  ) {
    return '$category ASR à l’étape $stage$chunk : $message';
  }

  @override
  String asrFailureChunkPosition(Object index, Object count) {
    return ', segment $index/$count';
  }

  @override
  String asrFailureRequestFailed(Object detail) {
    return 'Échec de la requête : $detail';
  }

  @override
  String asrChunkAllFailed(Object count) {
    return 'Échec de la transcription par segments ($count segments, aucun réussi)';
  }

  @override
  String asrChunkIncomplete(Object succeeded, Object count) {
    return 'La transcription par segments est incomplète ($succeeded/$count segments réussis)';
  }

  @override
  String asrChunkSucceeded(Object detail) {
    return 'Réussi : $detail';
  }

  @override
  String asrChunkFailed(Object detail) {
    return 'Échec : $detail';
  }

  @override
  String asrChunkUncertain(Object detail) {
    return 'Résultat incertain : $detail';
  }

  @override
  String asrChunkDetails(
    Object index,
    Object start,
    Object end,
    Object status,
  ) {
    return 'Segment $index ($start–$end s) $status';
  }

  @override
  String asrChunkCheckpointFailure(Object detail) {
    return 'Échec de l’enregistrement de l’état du segment : $detail';
  }

